def pn(no: str) -> str:
    if no == "10bis":
        return "۱۰ مکرر/الحاقی"
    return str(no).translate(A2F)


def lookup_id(conn, table, column, value):
    row = conn.execute(f"SELECT id FROM {table} WHERE {column}=?", (value,)).fetchone()
    return row["id"] if row else None


def upsert_doc(conn, ref, title, short_title, type_code, authority, status, rat, eff, notes):
    row = conn.execute("SELECT id FROM documents WHERE reference_code=?", (ref,)).fetchone()
    if row:
        did = row["id"]
    else:
        did = get_or_create_document(
            conn, title=title, short_title=short_title, type_code=type_code,
            issuing_authority=authority, status_code=status,
            ratification_date=rat, effective_date=eff, reference_code=ref, notes=notes,
        )
    aid = lookup_id(conn, "authorities", "name_fa", authority)
    if aid is None:
        aid = conn.execute("INSERT INTO authorities(name_fa,authority_type) VALUES(?,?)", (authority, "legislative" if "مجلس" in authority else "judicial")).lastrowid
    conn.execute(
        """UPDATE documents SET title=?, short_title=?, type_id=?, issuing_authority_id=?, status_id=?,
           ratification_date=?, effective_date=?, notes=?, updated_at=CURRENT_TIMESTAMP WHERE id=?""",
        (title, short_title, lookup_id(conn, "document_types", "code", type_code), aid,
         lookup_id(conn, "statuses", "code", status), rat, eff, notes, did),
    )
    return did


def clear_owned(conn, did):
    # Preserve incoming document-level relations from other packages; owned relations are outgoing.
    conn.execute("DELETE FROM relations WHERE from_document_id=?", (did,))
    conn.execute("DELETE FROM articles_fts WHERE document_id=?", (did,))
    conn.execute("DELETE FROM articles WHERE document_id=?", (did,))
    conn.execute("DELETE FROM document_tags WHERE document_id=?", (did,))
    conn.execute("DELETE FROM document_topics WHERE document_id=?", (did,))


def decorate(conn, did, tags):
    link_document_topic(conn, did, "حقوق ثبت اسناد و املاک")
    link_document_topic(conn, did, "حقوق مدنی")
    for tag in tags:
        link_document_tag(conn, did, add_tag(conn, tag))


def add_rows(conn, did, ref, rows, eff, source, notes=None):
    out = {}
    for key, text in rows:
        out[key] = add_article(
            conn, did, article_no=pn(key), article_key=f"{ref}:{key}", version_no=1,
            is_current=1, effective_date=eff, text=text, source_note=source, notes=notes,
        )
    return out


